import {academic,courses,mappings,sources as academicSources,degreePlan,scenarios} from './academic-data.mjs';
import {normalizeCode,calculateRequirements,earnedUnits,validatePlan,estimateTimeline,validateBackup,defaultState,parseTerm,COURSE_STATUSES} from './engine.mjs';
import {specialties,frontiers,projects,futureSources,careerGuidance} from './future-data.mjs';
import {foundations,studyGuides,startTasks,advisingQuestions,campusOpportunities,resources} from './learning-content.mjs';
import {renderArmLab,renderControlLab,wireLabs} from './labs.mjs';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=v=>encodeURIComponent(v); const STORAGE='aerospace-plan-v1';
let state=defaultState(), undoState=null, pendingImport=null, saveOK=true;
try{const raw=localStorage.getItem(STORAGE);if(raw){const result=validateBackup(JSON.parse(raw));if(result.valid)state=result.data;else saveOK=false;}}catch{saveOK=false;}
const learningRefs=[...studyGuides.flatMap(g=>g.sources||[]),...campusOpportunities.flatMap(o=>o.sources||[]),...resources.map(r=>({title:r.title,url:r.url}))];
const seenSourceUrls=new Set([...academicSources,...futureSources].map(s=>s.url));const learningSources=learningRefs.filter(s=>{if(seenSourceUrls.has(s.url))return false;seenSourceUrls.add(s.url);return true}).map((s,i)=>({...s,id:`learning-${i}`,institution:'Learning & opportunity reference',checked:'2026-10-31',status:'Linked reference; access and future cycles require rechecking',use:'Supports the study method, learning resource or opportunity page.'}));
const allSources=[...academicSources,...futureSources,...learningSources];const sourceMap=Object.fromEntries(allSources.map(s=>[s.id,s]));
const getCourse=code=>courses.find(c=>c.code===normalizeCode(code));
const chip=(text,kind='')=>`<span class="pill ${kind}">${esc(text)}</span>`;
const list=items=>`<ul>${(items||[]).map(x=>`<li>${esc(typeof x==='string'?x:x.text||x.title||JSON.stringify(x))}</li>`).join('')}</ul>`;
const textList=items=>`<ul class="list-clean">${(items||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
const sourcesHTML=ids=>{const refs=(Array.isArray(ids)?ids:[ids]).filter(Boolean).map(v=>typeof v==='object'?v:sourceMap[v]).filter(Boolean);return refs.length?`<div class="citation">Evidence · ${refs.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`).join(' · ')}</div>`:''};
const btn=(text,href,kind='')=>`<a class="button ${kind}" href="${href}">${text} <span aria-hidden="true">↗</span></a>`;
const intro=(label,title,desc)=>`<div class="intro"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${desc}</p></div>`;
const crumbs=(label,href='#home',parent='Overview')=>`<div class="breadcrumb"><a href="${href}">${parent}</a> / ${esc(label)}</div>`;
const courseLink=code=>getCourse(code)?`<a href="#course/${id(code)}">${esc(code)}</a>`:esc(code);
function notice(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function persist(message){state.exportedAt=new Date().toISOString();try{localStorage.setItem(STORAGE,JSON.stringify(state));saveOK=true;if(message)notice(message);}catch{saveOK=false;notice('Browser storage is unavailable. Export a backup before leaving.');}}
function mutate(fn,message){undoState=structuredClone(state);fn(state);persist(message);if($('#undo'))$('#undo').disabled=false;}
function noteBox(key,label='Your field notes',placeholder='What did you notice? What will you test next?'){return `<label for="note-${esc(key)}" class="note-label">${label}<small>Saved in this browser</small></label><textarea id="note-${esc(key)}" data-note="${esc(key)}" placeholder="${esc(placeholder)}">${esc(state.notes[key]||'')}</textarea>`}
function taskRows(items){return items.map(t=>`<label class="checkrow ${state.tasks[t.id]===true?'completed':''}"><input type="checkbox" data-task="${t.id}" ${state.tasks[t.id]===true?'checked':''}><span><strong>${esc(t.title)}</strong><p>${esc(t.why||t.description||'')}</p><p><b>Done when:</b> ${esc(t.doneCriterion||t.done||'You have verified this step against your actual record.')}</p></span></label>`).join('')}
function home(){const finished=startTasks.filter(t=>state.tasks[t.id]===true).length;return `<section class="hero"><img class="hero-photo" src="assets/orbital-workshop.webp" alt="Concept illustration of robotic arms assembling a structure above Earth" fetchpriority="high"><div class="hero-inner"><div class="hero-copy"><span class="eyebrow">A life in aerospace · The journey begins here</span><h1>Become the engineer<br> the <em>future needs.</em></h1><p>From a page of mathematics to machines that work beyond Earth. A grounded path through college, real engineering, and the frontiers worth building for.</p><div class="actions">${btn('Explore your journey','#before','gold')}${btn('See the 2035+ frontier','#frontier','light')}</div></div></div><span class="hero-label">ORBITAL CONSTRUCTION · CONCEPT ART, NOT A FORECAST</span></section>
<section class="mission-strip"><div class="mission-strip-inner"><div><small>The direction</small><strong>Aerospace, with purpose.</strong></div><div><small>Starting point</small><strong>Southwestern <b>→</b> UCSD</strong></div><div><small>Target scenario</small><strong>2030 transfer <b>→</b> 2033 degree</strong></div><div><small>The deeper ambition</small><strong>Build. Test. Understand.</strong></div></div></section>
<section class="wrap"><div class="section-head"><div><span class="eyebrow">A map for the whole journey</span><h2>The horizon is big.<br>The next step is concrete.</h2></div><p>You do not need to become an aerospace engineer all at once. Build a sequence of capabilities, and collect evidence that each one is becoming yours.</p></div><div class="grid cols3"><a class="card card-link" href="#before"><span class="number">01</span><span class="eyebrow">Before transfer</span><h3>Build your launchpad.</h3><p>Rebuild the foundations, find the right college entry point, and connect every course to the next.</p><div class="bottom"><span>Readiness · Courses · Transfer</span><span>↗</span></div></a><a class="card card-link" href="#after"><span class="number">02</span><span class="eyebrow">After transfer</span><h3>Turn knowledge into judgment.</h3><p>Navigate the three-year UCSD sequence, choose depth deliberately, and learn through teams and testing.</p><div class="bottom"><span>Degree · Research · Capstone</span><span>↗</span></div></a><a class="card card-link" href="#frontier"><span class="number">03</span><span class="eyebrow">2035 and beyond</span><h3>Find work worth doing.</h3><p>Robots that repair. Habitats that endure. Machines that make human ambition physically possible.</p><div class="bottom"><span>Problems · People · Possibilities</span><span>↗</span></div></a></div><p class="welcome-note">The dates are a planning scenario. Placement, completed credit, admission, course availability, and sustainable workload determine the actual path. Your personal record starts empty.</p></section>
<section class="wrap rule"><div class="two-pane"><div><span class="eyebrow">Your next useful moves</span><h2>Start with what opens doors.</h2>${taskRows(startTasks.slice(0,4))}<div class="page-bottom"><a href="#before">View the full starting checklist →</a></div></div><aside class="aside-note"><span class="eyebrow">Keep the work visible</span><h3>A little more capable.</h3><p>${finished} of ${startTasks.length} starting actions checked. This is an administrative checklist, not a readiness score.</p><div class="progress-bar"><span style="width:${finished/startTasks.length*100}%"></span></div><p>Keep credit, understanding, and project evidence separate. Each matters. None is a substitute for the others.</p>${btn('Open my plan','#plan','text')}<small>${saveOK?'Progress stays in this browser.':'Storage could not be read. Export before leaving.'} <a href="#progress">Backup your work.</a></small></aside></div></section>
<section class="dark"><div class="wrap feature-split"><div><span class="eyebrow">A direction to grow into</span><h2>Make physical systems<br><em>work, reliably.</em></h2><p>Spacecraft mechanisms and robotics connect your interest in moving hardware with servicing, assembly, exploration, and places people could live. Controls and careful testing make that interest useful.</p><p>Let real projects test the fit. The right specialty is one whose daily problems hold your attention after the cinematic moment has passed.</p><div class="actions">${btn('Explore career depth','#careers','gold')}${btn('Start a small project','#projects','light')}</div></div><div><img src="assets/earth-workbench.webp" alt="Concept illustration of an engineering workbench and robotic mechanisms" loading="lazy"><small>Concept art from The Factory. Real competence comes from the evidence you build.</small></div></div></section>
<section class="wrap"><div class="section-head"><div><span class="eyebrow">Your connected learning world</span><h2>Give every tool a purpose.</h2></div><p>Use this plan to choose the work. Use the existing learning spaces to do it.</p></div><div class="grid cols3">${[['Math Prep','Understand the idea. Practise until you can explain it.','https://www.christrovato.com/math_prep'],['The Factory','Experiment with mechanisms, controls, and engineering models.','https://ditchthescroll.com/factory/'],['The Reading Atlas','Find the books that deepen the question you are working on.','https://ditchthescroll.com/books/']].map(([t,p,u])=>`<a class="card card-link" href="${u}"><h3>${t} ↗</h3><p>${p}</p></a>`).join('')}</div></section><div class="quote-band"><p>“The future becomes less abstract every time you understand one more thing.”</p><small>A WORKING PRINCIPLE FOR THE JOURNEY</small></div>`}
function before(){return `<section class="wrap">${intro('01 · Before transfer','Build the foundations.<br><em>Protect the sequence.</em>','The goal is to arrive prepared for the degree, with a workload you can actually sustain. Learning readiness, enrollment eligibility, and earned credit are different things.')}<div class="subnav"><a href="#foundations">Foundation bridge</a><a href="#courses">Course explorer</a><a href="#plan">Plan a scenario</a><a href="#schools">UCSD & SDSU</a></div><div class="timeline"><div><b>NOW → EARLY 2027</b><h3>Find your real starting point.</h3><p>Review skills; confirm placement, records and registration. A review topic is not automatically a required class.</p></div><div><b>SPRING 2027 ONWARD</b><h3>Build college momentum.</h3><p>Start manageable. Run useful general education alongside the math and science chain.</p></div><div><b>BEFORE APPLICATION</b><h3>Check each layer.</h3><p>Major preparation, UC units, the seven-course pattern, grades and timing all need their own review.</p></div><div><b>AFTER ADMISSION</b><h3>Reconcile the actual credit.</h3><p>Review the official evaluation, meet advisors and make room for university labs and group work.</p></div></div><div class="callout"><h3>2033 is a target scenario, not a countdown.</h3><p>UCSD explicitly publishes a three-year aerospace transfer plan. Fall 2030 transfer can lead toward a spring 2033 finish if prerequisites, admission, offerings, and enrollment intensity support it.</p>${sourcesHTML(['ucsd-program','ucsd-plan'])}</div><div class="two-pane"><div><span class="eyebrow">First enrollment</span><h2>Remove the uncertainty that matters.</h2>${taskRows(startTasks)}</div><aside class="aside-note"><h3>Spring 2027</h3><p>The published semester runs <b>February 1–May 28</b>. Public registration dates depend on student group; your personal appointment and available sections control what you can do.</p>${sourcesHTML('swc-schedule')}<hr><h3>A sustainable first term</h3><p>One demanding math course plus a carefully chosen additional class may teach you more about your real capacity than an overloaded schedule. Track actual hours before expanding.</p>${btn('Compare workload','#plan','text')}</aside></div></section><section class="dark"><div class="wrap"><span class="eyebrow">The path that can control the date</span><h2>Start the long chains early.</h2><div class="mini-map">${['Calculus I','Calculus II + Physics I','Calculus III + Physics II','Physics III + remaining math'].map((t,i)=>`${i?'<i>→</i>':''}<span>${t}</span>`).join('')}</div><p class="small" style="margin-top:18px">Conceptual dependency overview, not a term schedule. Physics, chemistry and programming have specific prerequisite and concurrent-enrollment rules. Explore the course records before putting them together.</p>${sourcesHTML(['swc-math','swc-physics','swc-engineering'])}</div></section><section class="wrap"><div class="section-head"><div><span class="eyebrow">Transfer readiness has layers</span><h2>One completed list is not enough.</h2></div></div><div class="grid cols2">${academic.facts.filter(f=>['screening','eligibility','seven-course','math-entry'].includes(f.id)).map(f=>`<div class="card"><h3>${({screening:'Major preparation',eligibility:'UC minimum eligibility','seven-course':'The seven-course pattern','math-entry':'Placement and actual understanding'})[f.id]}</h3><p>${esc(f.text)}</p>${sourcesHTML(f.sourceIds)}</div>`).join('')}</div><div class="callout warning"><h3>General education belongs beside the technical sequence.</h3><p>Writing helps you explain an argument and document a test. Humanities and social sciences help you understand people and consequences. Cal-GETC, UC eligibility, your UCSD college, and aerospace requirements are separate layers; certification does not automatically remove every university obligation.</p>${sourcesHTML(['uc-calgetc','ucsd-seventh','ucsd-revelle'])}</div>${btn('Inspect the course map','#courses')}${advisingSection()}</section>`}
function advisingSection(){return `<div class="page-bottom"><span class="eyebrow">Take better questions to advising</span><h2>Make the uncertain parts discussable.</h2>${academic.unresolved.map(q=>`<details><summary>${esc(q.question)}</summary><p>${esc(q.impact)}</p>${sourcesHTML(q.sourceIds)}</details>`).join('')}<p class="small" style="margin-top:20px">Personal placement, transcript, residency, eligibility, and finances are not inferred here. The plan is useful because those unknowns remain visible.</p>${btn('Export an advising summary','#progress','text')}</div>`}
function after(){return `<section class="wrap">${intro('02 · After transfer','From coursework<br>to <em>engineering judgment.</em>','At UCSD, the foundation becomes fluid mechanics, structures, controls, experimentation and design. The sequence matters as much as the course count.')}<div class="subnav"><a href="#after">The degree</a><a href="#after/specializations">Formal specializations</a><a href="#opportunities">Research & teams</a><a href="#projects">Portfolio ladder</a></div><div class="callout"><h3>The published nine-quarter transfer template</h3><p>This is the department’s currently linked three-year template, reviewed in 2025. It illustrates dependencies; it does not establish your future schedule. Articulated courses may free room without eliminating an entire year. TE = technical elective; GE = college/general education.</p>${sourcesHTML(['ucsd-plan','ucsd-catalog'])}</div>${degreePlan.map(y=>`<section class="page-bottom"><span class="eyebrow">University year ${y.year}</span><div class="grid cols3">${['fall','winter','spring'].map(season=>`<div class="term-block"><h3>${season[0].toUpperCase()+season.slice(1)}</h3>${y[season].map(code=>`<div class="question"><strong>${courseLink(code)}</strong><p>${esc(getCourse(code)?.title||(code==='TE'?'Technical elective — plan its prerequisite chain.':'College/general-education slot — verify actual remaining requirements.'))}</p></div>`).join('')}</div>`).join('')}</div></section>`).join('')}<div class="callout warning"><h3>Do not lose a year to an invisible dependency.</h3><p>The 2026–27 table shows MAE 113 and MAE 114 only in fall, with 113 required before 114. Taking 113 in the final fall leaves no ordinary later fall for 114. MAE 182 has no offering shown in that table. Plan electives early and ask the department about the actual future sequence.</p>${sourcesHTML(['ucsd-offerings','ucsd-courses'])}</div><div class="grid cols2"><div class="card"><h3>Track the whole degree.</h3><p>The aerospace catalog includes the lower-division foundation, upper-division core, laboratories, the MAE 155A–155B design sequence and five technical electives. University and college obligations remain separate.</p><p>${esc(academic.ucsdCoreNotes)}</p>${sourcesHTML(['ucsd-catalog','ucsd-seventh'])}</div><div class="card"><h3>Plan for real daytime work.</h3><p>Labs, office hours and team projects can conflict with employment. Approved UCSD part-time status is 10 or fewer quarter units and requires a new request each quarter. It does not guarantee a convenient sequence or preserve aid unchanged.</p>${sourcesHTML('ucsd-parttime')}</div></div><div class="page-bottom" id="formal-specializations"><span class="eyebrow">Choose depth deliberately</span><h2>Three formal options. Many professional directions.</h2><p>A UCSD aerospace specialization is optional; at most one may be declared. Four of the five technical electives follow the specialization pattern. Plan at least two years before graduation and declare at least one quarter before graduation.</p>${sourcesHTML('ucsd-specializations')}<div class="grid cols3" style="margin-top:30px">${academic.specializations.map(s=>`<article class="card"><h3>${esc(s.name)}</h3><p>${esc(s.work)}</p><b class="small">Anchor: ${courseLink(s.anchor)}</b><p class="small">Then choose three from the approved list: ${s.chooseThree.map(courseLink).join(', ')}.</p><details><summary>Planning watchpoints</summary><p>${esc(s.trap)}</p>${s.departmentAdditionalOption?`<p>${esc(s.departmentAdditionalOption)}</p>`:''}<p>Graduate courses on a list still require the applicable preparation and enrollment permission.</p></details></article>`).join('')}</div></div>${btn('Explore professional specialties','#careers','text')}</section>`}
function courseExplorer(){return `<section class="wrap">${intro('The course explorer','See what each course<br><em>makes possible.</em>','Search by title, current number, or an old calculus alias. Required preparation, degree work and optional enrichment stay visibly distinct.')}<div class="toolbar"><div><label for="course-query">Search courses</label><input id="course-query" type="search" placeholder="Calculus two, MATH 251, controls…"></div><div><label for="course-school">Institution</label><select id="course-school"><option value="all">Both institutions</option value="swc">Southwestern</option><option value="ucsd">UC San Diego</option></select></div></div><div id="course-results">${courseCards(courses)}</div></section>`}
function matchesCourse(c,q){const normalized=normalizeCode(q);return `${c.code} ${c.title} ${c.why} ${(c.aliases||[]).join(' ')}`.toLowerCase().includes(q.toLowerCase())||c.code===normalized||(q.toLowerCase().includes('calculus two')&&c.code==='MATH C2220')}
function courseCards(items){return `<p class="small">${items.length} course records. SWC units are semesters; UCSD units are quarters.</p><div class="grid cols3">${items.map(c=>`<a class="card card-link" href="#course/${id(c.code)}"><span class="eyebrow">${esc(c.code)} · ${c.units} ${c.unitSystem==='semester'?'semester':'quarter'} units</span><h3>${esc(c.title)}</h3><p>${esc(c.why||'Inspect prerequisites, credit relationships and source evidence.')}</p><div class="bottom"><span>${c.unitSystem==='semester'?'Southwestern College':'UC San Diego'}</span><span>↗</span></div></a>`).join('')}</div>`}
function courseDetail(code){const c=getCourse(code);if(!c)return missing();const maps=mappings.filter(m=>m.alternatives.some(route=>route.includes(c.code)));return `<section class="wrap">${crumbs(c.code,'#courses','Course explorer')}${intro(c.unitSystem==='semester'?'Before transfer · Southwestern College':'After transfer · UC San Diego',`${esc(c.code)}<br><em>${esc(c.title)}</em>`,esc(c.why||'Understand the requirement, then verify the route that applies to your academic record.'))}<div class="two-pane"><div><div class="tag-line">${chip(`${c.units} ${c.unitSystem} units`)}${chip(c.role||'Course record')}${chip('Evidence checked 2026-10-31','green')}</div><h2>What comes before this?</h2><p>${esc(c.prerequisiteNote||c.prereqNote||'The ordinary prerequisite route is shown below. Official placement, accepted equivalents and consent routes must be confirmed by the institution.')}</p>${(c.prerequisites?.length?c.prerequisites:c.indicativePrerequisites||[]).length?`<div class="mini-map">${(c.prerequisites?.length?c.prerequisites:c.indicativePrerequisites||[]).map((route,i)=>`${i?'<i>OR</i>':''}<span>${(Array.isArray(route)?route:[route]).map(courseLink).join(' + ')}</span>`).join('')}</div>`:'<div class="callout"><p>No complete automated prerequisite rule is recorded here. Check the catalog, placement and enrollment restrictions.</p></div>'}${c.prerequisiteScope?`<p class="small">${esc(c.prerequisiteWarning||c.prerequisiteScope)}</p>`:''}${c.corequisites?.length?`<h3 style="margin-top:30px">Concurrent or prior enrollment</h3><p>${c.corequisites.map(r=>r.map(courseLink).join(' + ')).join(' OR ')}</p>`:''}${c.approvalRoutes?.length?`<h3>Official alternatives to confirm</h3>${list(c.approvalRoutes)}`:''}<h2 style="margin-top:38px">How the credit connects</h2>${maps.length?maps.map(m=>`<div class="callout"><h3>${esc(m.target)}</h3><p>${m.alternatives.map(r=>r.map(courseLink).join(' <b>AND</b> ')).join(' <b>OR</b> ')}</p><p class="small">2026–27 Southwestern → UCSD Aerospace agreement. This relationship does not duplicate earned units or establish that a future agreement is unchanged.</p>${sourcesHTML('assist-aero')}</div>`).join(''):`<p>${c.unitSystem==='quarter'?'This is a UCSD degree-course record. Check your official evaluation for remaining credit.':'No UCSD aerospace equivalency is asserted here. Preparation can be useful without satisfying a mapped requirement.'}</p>`}<h3>Availability is a separate question.</h3><p>${esc(c.offerings?.note||c.offeringNote||'The catalog establishes the course; the term schedule establishes whether an appropriate section is actually offered. Future availability is an assumption until published.')}</p>${sourcesHTML(c.sourceIds||[c.source]||[])}</div><aside class="aside-note"><h3>Put it in a scenario.</h3><p>Adding a course starts a planning record. It does not mark credit completed or verify eligibility.</p><button class="button" data-add-course="${esc(c.code)}">Add to my plan +</button><p class="small" style="margin-top:20px">Use your official course code, term and grade. A completion without verified evidence stays unknown.</p><hr><h3>Make it meaningful.</h3><p>For every new method, ask: What physical quantity does this describe? What assumptions make it valid? How could I check the result?</p><a href="#projects">Find an application →</a></aside></div><div class="page-bottom">${noteBox(`course-${c.code}`,'Questions to take to advising')}</div></section>`}
function schools(){return `<section class="wrap">${crumbs('UCSD & SDSU','#before','Before transfer')}${intro('Two local paths','Choose by fit.<br><em>Then verify the details.</em>','UCSD is the primary direction for this plan. SDSU is a serious local aerospace alternative with its own preparation, curriculum, calendar and admission rules.')}<div class="table-wrap"><table><thead><tr><th>Consideration</th><th>UC San Diego</th><th>San Diego State</th></tr></thead><tbody>${academic.schoolComparison.map(r=>`<tr><th>${esc(r.factor)}</th><td>${esc(r.UCSD)}${sourcesHTML(r.sources)}</td><td>${esc(r.SDSU)}</td></tr>`).join('')}</tbody></table></div><div class="callout warning"><h3>Keep the two eligibility checks separate.</h3><p>SDSU's fall 2027 aerospace minimum of 2.70 is a minimum, not a prediction or a goal. The CSU Golden Four and applicable major preparation need their own audit. No SWC-to-SDSU course mapping is assumed by this planner.</p>${sourcesHTML(['sdsu-gpa','sdsu-transfer','sdsu-pathways'])}</div><div class="grid cols2"><article class="card"><h3>Compare a real week.</h3><p>Find an actual term schedule. Plot class, lab, team and commute hours against paid work. Neither program is established here as an evening engineering degree.</p></article><article class="card"><h3>Compare a real opportunity.</h3><p>Read a lab's undergraduate instructions, a team's current recruitment page, and the actual equipment-access rules. A research theme is a lead, not an invitation.</p></article></div>${noteBox('school-comparison','Your decision evidence','What would make one school materially better for your actual situation?')}</section>`}

function missing(){return `<section class="wrap"><h1>That page is not in the field guide.</h1><p>Use the navigation or search to find the next connection.</p>${btn('Return to overview','#home')}</section>`}

const planningDefaults={name:'My target journey',startYear:2027,startSeason:'spring',transferYear:2030,mathEntry:'precalculus',unitsPerTerm:9,summer:false,summerUnits:3,completedUnits:0,universityYears:3,weeklyCapacity:24,weeklyHours:27,classHours:9,labHours:3,practiceHours:12,travelHours:3,workHours:40,otherHours:15,restHours:56,unitFee:46,books:250,transport:300,fees:100};
function planInputs(){const raw=state.preferences.plan||{},p={...planningDefaults};for(const k of Object.keys(p)){if(typeof p[k]==='number'){const v=Number(raw[k]);if(Number.isFinite(v)&&v>=0&&v<=100000)p[k]=v;}else if(typeof p[k]==='boolean')p[k]=raw[k]===true;else if(typeof raw[k]==='string')p[k]=raw[k].slice(0,80);}p.postTransferPartTime=raw.postTransferPartTime===true;p.mathEntry=['calculus','precalculus','algebra'].includes(p.mathEntry)?p.mathEntry:'precalculus';p.startSeason=p.startSeason==='fall'?'fall':'spring';p.startYear=Math.max(2027,Math.min(2050,p.startYear));p.transferYear=Math.max(p.startYear+1,Math.min(2060,p.transferYear));p.universityYears=Math.max(3,Math.min(8,p.universityYears));p.unitsPerTerm=Math.min(24,p.unitsPerTerm);p.weeklyHours=p.classHours+p.labHours+p.practiceHours+p.travelHours;return p}
function timelineResult(p){const available=Math.max(0,168-p.workHours-p.otherHours-p.restHours);const r=estimateTimeline({...p,weeklyCapacity:Math.min(p.weeklyCapacity,available)});return `<div class="grid cols3"><div class="card"><span class="stat-label">Requested transfer</span><span class="stat">${p.transferYear}</span><p>Fall intake · preparation by the preceding spring</p></div><div class="card"><span class="stat-label">Degree target</span><span class="stat">${r.graduationYear}${p.postTransferPartTime?'+':''}</span><p>Three-year university baseline; conditional on actual sequencing</p></div><div class="card"><span class="stat-label">Capacity check</span><span class="stat">${p.weeklyHours}<small> / ${p.weeklyCapacity} h</small></span><p>Estimated course commitment / declared available time per week</p><p class="small">Whole-week check: ${p.workHours+p.otherHours+p.restHours+p.weeklyHours} of 168 hours accounted for. ${available} hours remain after work, other commitments and the entered sleep/recovery reserve. All values are assumptions.</p></div></div><div class="callout ${r.targetFeasible?'':'warning'}"><h3>${r.targetFeasible?'These broad assumptions fit the target.':'This target has a visible constraint.'}</h3><p>${r.targetFeasible?'This is a coarse feasibility check, not a validated semester schedule. Confirm the actual courses, grades, GE, transferable units, admission and sections below.':`The earliest unit-and-sequence bound under these assumptions is fall ${r.earliestTransferYear??'not reachable'}, before accounting for admission and actual offerings. A later date alone does not fix an overloaded week.`}</p>${r.bottlenecks.map(s=>`<p>${esc(s)}</p>`).join('')}<details><summary>Inspect the assumptions</summary>${list(r.assumptions)}</details></div>`}
function plan(){const p=planInputs();return `<section class="wrap">${intro('My plan · Browser-local workspace','Make the path<br><em>honest and workable.</em>','Change a scenario, move courses between terms, and see what needs attention. Nothing is counted as official credit just because it appears here.')}<div class="subnav"><a href="#plan">Timeline & course plan</a><a href="#plan/requirements">Requirement check</a><a href="#progress">Notes & backup</a></div><div class="grid cols3">${academic.scenarioAssumptions.map((s,i)=>`<button class="card" data-preset="${i}" style="text-align:left"><span class="eyebrow">${esc(s.name)}</span><h3>${s.transferFall} → ${s.graduateSpring}</h3><p>${esc(s.conditions)}</p><span class="small">Use this target →</span></button>`).join('')}</div><div class="page-bottom"><h2>Choose assumptions you can inspect.</h2><form id="scenario-form"><div class="form-grid"><div><label for="scenario-name">Scenario name</label><input id="scenario-name" name="name" maxlength="80" value="${esc(p.name)}"></div><div><label for="start-year">College start year</label><input id="start-year" name="startYear" type="number" min="2027" max="2050" value="${p.startYear}"></div><div><label for="start-season">Starting term</label><select id="start-season" name="startSeason"><option value="spring" ${p.startSeason==='spring'?'selected':''}>Spring</option><option value="fall" ${p.startSeason==='fall'?'selected':''}>Fall</option></select></div><div><label for="transfer-year">Target fall transfer</label><input id="transfer-year" name="transferYear" type="number" min="2028" max="2060" value="${p.transferYear}"></div><div><label for="math-entry">Starting math assumption</label><select id="math-entry" name="mathEntry">${[['precalculus','One preparation term assumed'],['calculus','Calculus-ready assumption'],['algebra','Two preparation terms assumed']].map(([v,t])=>`<option value="${v}" ${p.mathEntry===v?'selected':''}>${t}</option>`).join('')}</select><p class="field-hint">A scenario input, not a placement decision or required remedial enrollment.</p></div><div><label for="units-term">Transferable semester units / term</label><input id="units-term" name="unitsPerTerm" type="number" min="0" max="24" step="1" value="${p.unitsPerTerm}"></div><div><label for="completed-units">Already confirmed UC-transferable semester units</label><input id="completed-units" name="completedUnits" type="number" min="0" max="150" value="${p.completedUnits}"><p class="field-hint">Separate from the course subtotal; enter only a verified evaluation.</p></div><div><label for="summer-units">Optional summer semester units</label><input id="summer-units" name="summerUnits" type="number" min="0" max="15" value="${p.summerUnits}"><label class="checkrow"><input name="summer" type="checkbox" ${p.summer?'checked':''}> Include earlier summers</label></div><div><label for="university-years">University years</label><input id="university-years" name="universityYears" type="number" min="3" max="8" value="${p.universityYears}"><label class="checkrow"><input name="postTransferPartTime" type="checkbox" ${p.postTransferPartTime?'checked':''}> Reduced university load assumed</label></div></div><div class="callout"><h3>Give the workload its real shape.</h3><p>These are editable estimates. Actual lab and meeting hours should replace them once sections are published. Course hours below include class, laboratory, independent practice and travel; there is no universal hours-per-unit rule.</p><div class="form-grid">${[['classHours','Class meetings / week'],['labHours','Laboratory / week'],['practiceHours','Independent study / week'],['travelHours','Travel & group work / week'],['weeklyCapacity','Hours available for college / week'],['workHours','Paid work / week'],['otherHours','Other waking commitments / week'],['restHours','Sleep & recovery reserve / week']].map(([k,t])=>`<div><label for="${k}">${t}</label><input id="${k}" name="${k}" type="number" min="0" max="100" step="1" value="${p[k]}"></div>`).join('')}</div></div><div class="actions"><button class="button" type="submit">Update scenario →</button><button type="button" id="save-scenario">Save named snapshot</button><button type="button" id="undo" ${undoState?'':'disabled'}>Undo last edit</button></div></form></div><div class="page-bottom" id="scenario-result">${timelineResult(p)}</div>${state.scenarios.length?`<h3>Saved scenarios</h3><div class="grid cols3">${state.scenarios.map((s,i)=>`<div class="card"><h3>${esc(s.name||'Scenario')}</h3><p>${esc(s.inputs?.transferYear||2030)} transfer · ${s.courseRecords?.length||0} course records</p><button data-load-scenario="${i}">Load snapshot</button></div>`).join('')}</div>`:''}<div class="page-bottom"><div class="section-head"><div><span class="eyebrow">Your actual course records</span><h2>Plan a course. Inspect its dependencies.</h2></div><a href="#courses">Explore course meanings ↗</a></div><form id="add-record" class="toolbar"><div><label for="record-course">Course</label><select id="record-course">${courses.map(c=>`<option value="${c.code}">${c.code} · ${esc(c.title)}</option>`).join('')}</select></div><div><label for="record-term">Term (year-season)</label><input id="record-term" value="2027-spring" pattern="[0-9]{4}-(spring|summer|fall|winter)" required></div><button class="button">Add planned course +</button></form><div id="course-records">${recordList()}</div></div><div class="page-bottom" id="plan-validation">${validationHTML()}</div><div class="page-bottom" id="requirements">${requirementsHTML()}</div><div class="page-bottom"><h2>Cost: keep the pieces separate.</h2><p>Current resident enrollment baseline: $46 per semester unit. Residency, other charges and financial aid remain unverified. This estimates a single community-college term, not the full degree.</p><div class="form-grid">${[['unitFee','Enrollment fee / unit ($)'],['books','Books & materials / term ($)'],['transport','Transportation / term ($)'],['fees','Other campus fees / term ($)']].map(([k,t])=>`<div><label for="cost-${k}">${t}</label><input id="cost-${k}" data-cost="${k}" type="number" min="0" max="100000" value="${p[k]}"></div>`).join('')}</div><div id="cost-result" class="callout">${costHTML(p)}</div>${sourcesHTML('swc-fees')}<p class="small">Add housing, equipment and changes in work income privately before making a decision. University cost estimates need their own current-year review: <a href="https://fas.ucsd.edu/cost-of-attendance/undergraduates/index.html" target="_blank" rel="noopener">UCSD official cost of attendance ↗</a>.</p></div>${advisingSection()}</section>`}
function costHTML(p){return `<b>Illustrative term subtotal: $${(Number(p.unitsPerTerm)*Number(p.unitFee)+Number(p.books)+Number(p.transport)+Number(p.fees)).toLocaleString()}</b><p class="small">${p.unitsPerTerm} semester units × $${p.unitFee}, plus entered materials, transport and fees. Before housing, income changes, aid and other personal expenses.</p>`}
function recordList(){if(!state.courseRecords.length)return `<div class="empty">No personal academic records entered. Add a planned course to start. Your transcript and grades are unknown.</div>`;return state.courseRecords.map(r=>`<article class="plan-record"><div class="record-head"><div><h3>${courseLink(r.code)}</h3><small>${esc(getCourse(r.code)?.title||'Custom course — equivalency unknown')}</small></div><button data-remove-record="${r.id}">Remove</button></div><div class="record-fields"><div><label for="term-${r.id}">Term</label><input id="term-${r.id}" data-record="${r.id}" data-field="term" value="${esc(r.term||'')}" placeholder="2027-spring" pattern="[0-9]{4}-(spring|summer|fall|winter)"></div><div><label for="status-${r.id}">Record status</label><select id="status-${r.id}" data-record="${r.id}" data-field="status">${COURSE_STATUSES.map(s=>`<option ${s===r.status?'selected':''} value="${s}">${s}</option>`).join('')}</select></div><div><label for="grade-${r.id}">Letter grade</label><select id="grade-${r.id}" data-record="${r.id}" data-field="grade"><option value="">Unknown / pending</option>${['A+','A','A-','B+','B','B-','C+','C','C-','D','F','P','NP','W','I'].map(g=>`<option ${g===r.grade?'selected':''}>${g}</option>`).join('')}</select></div><div><label class="verify"><input type="checkbox" data-record="${r.id}" data-field="verified" ${r.verified?'checked':''}> Checked against record</label></div></div></article>`).join('')}
function validationHTML(){const v=validatePlan(state.courseRecords,courses);return `<h2>What needs attention?</h2><p class="small">Checks cover recorded SWC prerequisite routes and term order. Official alternatives and UCSD's full prerequisite language still need review. Unentered credit is not assumed. Future sections are not guaranteed.</p>${v.issues.length?v.issues.map(x=>`<div class="issue ${x.severity==='warning'?'':'info'}"><b>${esc(x.code)}:</b> ${esc(x.message)}</div>`).join(''):`<div class="callout"><p>${state.courseRecords.length?'No conflicts found in the automated rules represented here. This does not certify enrollment eligibility.':'Add courses to inspect dependency conflicts.'}</p></div>`}${v.assumptions?.length?`<details><summary>Offering and prerequisite limits</summary>${list(v.assumptions)}</details>`:''}`}
function requirementsHTML(){const results=calculateRequirements(state.courseRecords,mappings), units=earnedUnits(state.courseRecords,courses);const screening=['MATH 18','MATH 20A','MATH 20B','MATH 20C','MATH 20D','CHEM 6A','PHYS 2A','PHYS 2B','PHYS 2C','PHYS 2CL'];const satisfied=results.filter(r=>screening.includes(r.target)&&r.status==='satisfied').length;return `<span class="eyebrow">Separate the layers</span><h2>Requirement check</h2><p>${satisfied} of ${screening.length} current major screening requirements supported by verified completed records. This is not an admission probability or a complete eligibility audit.</p><div class="grid cols3"><div class="card"><span class="stat">${units.semester}</span><p>Verified completed semester-unit subtotal from entered courses. UC transferability is a separate evaluation.</p></div><div class="card"><span class="stat">${units.quarter}</span><p>Verified quarter-unit subtotal. Quarter and semester units are never added here.</p></div><div class="card"><span class="stat">${units.unverifiedSemester}</span><p>Semester units marked completed but not verified in the planner. Not counted above.</p></div></div><div class="table-wrap" style="margin-top:25px"><table><thead><tr><th>UCSD requirement</th><th>SWC route — AND / OR preserved</th><th>Record status</th><th>Role</th></tr></thead><tbody>${results.map(r=>{const m=mappings.find(m=>m.id===r.id);return `<tr><td>${courseLink(r.target)}</td><td>${m.alternatives.map(a=>a.map(courseLink).join(' <b>AND</b> ')).join(' <b>OR</b> ')}</td><td>${chip(r.status,r.status==='satisfied'?'green':r.status==='unknown'?'amber':'')}<p>${esc(r.explanation)}</p></td><td>${screening.includes(r.target)?'Admission screening':r.target==='MAE 8'?'Recommended preparation; degree required':'Degree preparation'}</td></tr>`}).join('')}</tbody></table></div>${sourcesHTML(['assist-aero','ucsd-screening'])}<div class="callout warning"><h3>Keep units honest.</h3><p>MATH 252 can cover 20C and 20E while earning its four semester units only once. ENGR 250 <b>and</b> 251 jointly cover MAE 30A; 251 also covers 30B without duplicating its units. MATH 253 <b>or</b> ENGR 280 is an alternative route to 20D.</p></div><h3>Other eligibility layers — self-checks, not automatic approval</h3>${taskRows([{id:'60units',title:'Verify 60 UC-transferable semester units (or 90 quarter units)',why:'Course subtotals alone are not a transferability evaluation.',doneCriterion:'Official records and an advising review establish the transferable total.'},{id:'7pattern',title:'Audit the seven-course pattern and required grades',why:'Two composition courses, one quantitative reasoning course and four courses across at least two specified areas.',doneCriterion:'The actual classes and grades have been reviewed against the UC pattern.'},{id:'gpa',title:'Check GPA, good standing and application-cycle obligations',why:'Minimums do not establish competitive selection or admission.',doneCriterion:'The official application requirements for your intended entry year have been reviewed.'},{id:'gecollege',title:'Review Cal-GETC and eventual college obligations',why:'Certification and college requirements are different from major screening.',doneCriterion:'The receiving college and advisors have reviewed what remains.'}])}${sourcesHTML(['ucsd-transfer','uc-calgetc'])}`}

const frontierImages=['orbital-workshop.webp','lunar-workshop.webp','orbital-workshop.webp','lunar-workshop.webp','ocean-resident.webp','earth-workbench.webp','orbital-workshop.webp','earth-workbench.webp'];
function frontier(){return `<section class="hero frontier-hero"><img class="hero-photo" src="assets/lunar-workshop.webp" alt="Concept illustration of construction and engineering activity on the Moon"><div class="hero-inner"><div class="hero-copy"><span class="eyebrow">2035 & beyond · A frontier of useful problems</span><h1>Somebody will have<br>to make <em>it work.</em></h1><p>The future will need more than bold ideas. It will need people who can understand a system, build it, test it, repair it—and tell the truth about its limits.</p>${btn('Find your technical direction','#careers','gold')}</div></div><span class="hero-label">LUNAR WORKSHOP · SPECULATIVE CONCEPT ART</span></section><section class="wrap"><div class="section-head"><div><span class="eyebrow">Eight problems worth preparing for</span><h2>Think beyond the vehicle.</h2></div><p>These are conditional 2035+ scenarios grounded in work visible today. Mission dates, commercial scale, hiring and economics remain uncertain. The skills are useful across many futures.</p></div><div class="grid cols2">${frontiers.map((f,i)=>`<a class="card card-link frontier-card" href="#frontier/${f.id}"><img class="scene" src="assets/${frontierImages[i]}" alt="Speculative ${i===4?'undersea':'space engineering'} concept illustration" loading="lazy"><div class="card-body"><span class="eyebrow">0${i+1} · ${esc(f.horizon)}</span><h3>${esc(f.title)}</h3><p>${esc(f.problem)}</p><div class="bottom"><span>Today's foundations → tomorrow's work</span><span>↗</span></div></div></a>`).join('')}</div></section><section class="dark"><div class="wrap feature-split"><div><span class="eyebrow">What you can carry across futures</span><h2>Become good at the<br><em>durable problems.</em></h2><p>A spacecraft, an ocean robot and a lunar workshop each need models, measurements, feedback, materials, power, interfaces and a way to recover when something goes wrong.</p><p>Learn the physical principles deeply. Use tools fluently. Build proof that you can tell when an answer is wrong.</p></div><div>${careerGuidance.motivation.slice(0,3).map(m=>`<div class="question"><h3>${esc(m.title)}</h3><p>${esc(m.body)}</p></div>`).join('')}</div></div></section><section class="wrap"><div class="grid cols2"><div class="card"><span class="eyebrow">A separate optional ambition</span><h3>What if you want to work in space?</h3><p>Building space systems and being selected to fly are different paths. No engineering specialty guarantees a seat. Deep competence, operational judgment and teamwork can matter while your Earth-based career remains meaningful.</p>${btn('Explore the human-spaceflight branch','#spaceflight','text')}</div><div class="card"><span class="eyebrow">The work starts much smaller</span><h3>Make one honest artifact.</h3><p>A measured experiment. A mechanism with known coordinates. A model checked against a special case. Those are small versions of the habits that make ambitious work possible.</p>${btn('Find the next project','#projects','text')}</div></div></section>`}
function frontierDetail(slug){const f=frontiers.find(f=>f.id===slug);if(!f)return missing();const i=frontiers.indexOf(f);return `<section class="hero frontier-hero"><img class="hero-photo" src="assets/${frontierImages[i]}" alt="Speculative engineering concept scene"><div class="hero-inner"><div class="hero-copy"><span class="eyebrow">${esc(f.horizon)} · Problem ${i+1} of ${frontiers.length}</span><h1 style="font-size:clamp(35px,4.5vw,61px)">${esc(f.title)}</h1><p>${esc(f.scene)}</p></div></div><span class="hero-label">CONCEPT ART · A SCENARIO, NOT A PROMISE</span></section><section class="wrap">${crumbs(f.title,'#frontier','2035 & beyond')}<div class="two-pane"><article class="article"><span class="eyebrow">The engineering beneath the vision</span><h2>${esc(f.problem)}</h2><h3>What already exists today</h3><p>${esc(f.today)}</p>${sourcesHTML(f.sources)}<h3>The contribution you could make</h3><p>${esc(f.yourContribution)}</p><h3>What you can start learning now</h3><p>${esc(f.startNow)}</p><div class="callout warning"><h3>What remains uncertain</h3><p>${esc(f.uncertainty)}</p><p class="small">${esc(f.status)}</p></div><blockquote>You do not need certainty about 2035 to make this week's understanding useful.</blockquote></article><aside class="aside-note"><h3>Build toward this problem</h3><span class="eyebrow">Relevant depth</span>${textList(f.themes.map(t=>specialties.find(s=>s.id===t)?.title||t))}<span class="eyebrow" style="margin-top:30px">An experiment you can do</span>${f.projects.map(pid=>{const p=projects.find(p=>p.id===pid);return p?`<p><a href="#project/${pid}">${esc(p.title)} →</a></p>`:''}).join('')}<button data-save-frontier="${f.id}">${state.preferences.savedFrontiers?.includes(f.id)?'Saved to notebook ✓':'Save this frontier'}</button></aside></div><div class="page-bottom">${noteBox(`frontier-${f.id}`,'Why does this problem pull you in?','Name one physical question you would enjoy understanding, even if this exact future never happens.')}</div><div class="actions page-bottom">${btn('Explore the specialties','#careers')}${btn('Back to the frontier','#frontier','light')}</div></section>`}
function careers(){return `<section class="wrap">${intro('Professional directions · Explore before committing','Find your depth.<br><em>Keep your range.</em>',esc(careerGuidance.body))}<div class="grid cols2">${careerGuidance.depthHypotheses.map(h=>`<article class="card"><span class="eyebrow">A hypothesis to test</span><h3>${esc(h.title)}</h3><p>${esc(h.question)}</p><div class="actions">${h.projects.slice(0,2).map(pid=>`<a href="#project/${pid}">${esc(projects.find(p=>p.id===pid)?.title)} →</a>`).join('')}</div></article>`).join('')}</div><div class="callout"><p>${esc(careerGuidance.decisionRule)}</p><p class="small">${esc(careerGuidance.payNote)}</p></div><div class="toolbar"><div><label for="career-query">Search specialties</label><input id="career-query" type="search" placeholder="Mechanisms, thermal, underwater…"></div><a href="https://www.christrovato.com/aero_specialization_decision" class="button light">Full 26-path atlas ↗</a></div><div id="career-results">${careerCards(specialties)}</div><section class="page-bottom"><span class="eyebrow">What employers actually describe today</span><h2>Read the work, then the title.</h2><p>These are dated examples, not a list of promised openings or a forecast for graduation. Entry-level and experienced expectations are deliberately separated.</p>${careerGuidance.snapshots.map(s=>`<details><summary>${esc(s.employer)} · ${esc(s.role)}</summary><div class="tag-line" style="margin-top:18px">${chip(s.level,'blue')}${chip(s.location)}</div><p><b>Work:</b> ${esc(s.tasks)}</p><p><b>Requirements context:</b> ${esc(s.minimum)}</p>${s.preferred?`<p><b>Preferred:</b> ${esc(s.preferred)}</p>`:''}<p><b>Constraints:</b> ${esc(s.constraints)}</p><p class="small">${esc(s.evidence)}</p>${sourcesHTML(s.sources)}</details>`).join('')}</section><div class="page-bottom">${btn('Compare your strongest interests','#progress','text')}</div></section>`}
function careerCards(items){return `<div class="grid cols3">${items.map(s=>`<a class="card card-link" href="#career/${s.id}"><span class="eyebrow">Professional specialty</span><h3>${esc(s.title)}</h3><p>${esc(s.tagline)}</p><div class="bottom"><span>Work · Skills · Tradeoffs</span><span>↗</span></div></a>`).join('')}</div>`}
function careerDetail(slug){const s=specialties.find(s=>s.id===slug);if(!s)return missing();return `<section class="wrap">${crumbs(s.title,'#careers','Career directions')}${intro('Professional depth — not a formal degree label',`${esc(s.title)}`,esc(s.question))}<div class="two-pane"><article class="article"><h2>The actual work</h2><p>${esc(s.work)}</p><h3>Specialties inside the specialty</h3>${list(s.subspecialties)}<h3>What convincing evidence looks like</h3><p>${esc(s.evidence)}</p><h3>Tools and the thinking behind them</h3><p>${esc(s.tools)}</p><div class="callout"><h3>You may enjoy this if…</h3><p>${esc(s.fit)}</p></div><div class="callout warning"><h3>Watch the tradeoff</h3><p>${esc(s.watchOut)}</p></div>${sourcesHTML(s.sources)}</article><aside class="aside-note"><h3>Build from fundamentals.</h3>${list(s.fundamentals)}<h3>Try the work.</h3>${s.projects.map(pid=>`<p><a href="#project/${pid}">${esc(projects.find(p=>p.id===pid)?.title||pid)} →</a></p>`).join('')}<label for="interest-${s.id}">Your current interest</label><select id="interest-${s.id}" data-interest="${s.id}">${['Unexplored','Curious','Testing through a project','Strong fit','Not my direction'].map(v=>`<option ${state.preferences.interests?.[s.id]===v?'selected':''}>${v}</option>`).join('')}</select></aside></div><div class="page-bottom">${noteBox(`career-${s.id}`,'Evidence of fit','What did you enjoy doing? What did you avoid? What did you understand well enough to explain?')}</div></section>`}
function spaceflight(){return `<section class="wrap">${crumbs('Working in space','#frontier','2035 & beyond')}${intro('An optional branch, not the measure of success','Build a meaningful career.<br><em>Keep the flight ambition open.</em>','Designing space systems can be rewarding whether or not you ever leave Earth. The selection path to fly needs its own evidence, qualifications and opportunities.')}<div class="two-pane"><article class="article"><h2>There are several different ambitions here.</h2>${list(['Build spacecraft and habitat systems from Earth.','Support missions through integration, test and operations.','Be selected by an astronaut agency.','Be hired or sponsored for a commercial mission.','Spend an extended period living and working in space.'])}<p>One does not automatically lead to the next. A brief commercial flight is not the same as a months-long engineering assignment. Early station business models and crew requirements may change substantially before the 2030s.</p><h3>Use the current selection announcement.</h3><p>Agency recruitment has specific nationality, education, experience and medical requirements. Check the future vacancy that you would actually apply to. A list of historical astronaut degrees does not reveal your personal selection odds.</p><div class="citation">Primary references · <a href="https://www.nasa.gov/humans-in-space/astronauts/become-an-astronaut/" target="_blank" rel="noopener">NASA astronaut requirements</a> · <a href="https://www.nasa.gov/humans-in-space/becoming-an-astronaut-frequently-asked-questions/" target="_blank" rel="noopener">NASA selection FAQ</a></div><h3>Prepare through useful work.</h3><p>Learn to own a subsystem responsibly. Build test discipline, clear communication, fault diagnosis, operational judgment and the ability to work well with others. Choose technical depth you would still value if no flight opportunity arrives.</p><h3>Robotics contains a productive tension.</h3><p>Robots can expand activity in space while reducing the need to send people for individual tasks. Becoming a robotics engineer is a powerful way to contribute; it is not a promise that someone will send you to maintain your robot.</p><blockquote>A reliable system can carry your work farther than you personally travel.</blockquote></article><aside class="aside-note"><h3>A useful sequence</h3><ol class="steps"><li><b>Build competence</b><p>Earn the degree, develop evidence, learn through real teams.</p></li><li><b>Build operational credibility</b><p>Practice reliable decisions, documentation, testing and teamwork.</p></li><li><b>Check actual eligibility</b><p>Read current recruitment, role and mission requirements.</p></li><li><b>Apply when the fit is real</b><p>Selection, training and assignment are separate milestones.</p></li></ol></aside></div>${noteBox('spaceflight','What makes this ambition meaningful to you?')}</section>`}
function projectList(){return `<section class="wrap">${intro('Build & learn · A ladder of evidence','Make the ideas tangible.<br><em>Then make them trustworthy.</em>','Twelve projects grow from measurement to systems integration. Each has a question, a minimal version, a check and a stopping point. Start at your current understanding.')}<div class="grid cols2"><a class="card card-link" href="#lab/arm"><span class="eyebrow">Interactive explanation</span><h3>A robot arm is a coordinate problem.</h3><p>Change two joint angles and watch trigonometry become a physical position.</p><span>Open the geometry bench →</span></a><a class="card card-link" href="#lab/control"><span class="eyebrow">Interactive explanation</span><h3>What does feedback change?</h3><p>Explore response speed, steady-state error and the assumptions inside a simple model.</p><span>Open the feedback bench →</span></a></div><div class="toolbar page-bottom"><div><label for="project-filter">Project stage</label><select id="project-filter"><option value="all">All stages</option>${[...new Set(projects.map(p=>p.stage))].map(s=>`<option>${esc(s)}</option>`).join('')}</select></div></div><div id="project-results">${projectCards(projects)}</div><div class="callout"><h3>One complete case study beats a pile of unexplained demos.</h3><p>Keep the question, assumptions, alternatives, calculations, test results, failures, revisions and limitations together. Be able to explain the work without a generated script.</p></div></section>`}
function projectCards(items){return `<div class="grid cols3">${items.map(p=>`<a class="card card-link project-card" href="#project/${p.id}"><div class="project-top"><span class="number">${String(p.number).padStart(2,'0')}</span><small>${esc(p.stage)}</small></div><div class="card-body"><h3>${esc(p.title)}</h3><p>${esc(p.question)}</p><div class="bottom"><span>${esc(state.projects[p.id]?.status||'Not started')}</span><span>↗</span></div></div></a>`).join('')}</div>`}
function projectDetail(slug){const p=projects.find(p=>p.id===slug);if(!p)return missing();const record=state.projects[p.id]||{};return `<section class="wrap">${crumbs(p.title,'#projects','Build & learn')}${intro(`Project ${String(p.number).padStart(2,'0')} · ${esc(p.stage)}`,esc(p.title),esc(p.question))}<div class="two-pane"><article class="article"><h2>The smallest useful version</h2><p>${esc(p.minimum)}</p><h3>What to keep as evidence</h3>${list(p.deliverables)}<div class="callout"><h3>How to check it</h3><p>${esc(p.verify)}</p></div><h3>When to stop and review</h3><p>${esc(p.stopWhen)}</p><h3>A meaningful extension</h3><p>${esc(p.extension)}</p><div class="callout warning"><h3>The understanding check</h3><p>${esc(p.explainWithoutAI)}</p><p class="small">If a tool generated code or a calculation, explain its inputs, assumptions and a result you checked independently. A working screen is not sufficient evidence of understanding.</p></div><h3>Your test record</h3>${noteBox(`project-${p.id}`,'Question → prediction → test → result → revision','What did you predict? What did you measure? Where did the model disagree? What would you change?')}${sourcesHTML(p.sources)}<p class="small">${esc(p.sourceUse)}</p></article><aside class="aside-note"><span class="eyebrow">Before you begin</span><h3>Useful preparation</h3>${list(p.prerequisites)}<h3>Tools</h3>${list(p.tools)}<h3>Cost assumption</h3><p>$${p.costUSD[0]}–$${p.costUSD[1]} · ${esc(p.costBasis)}</p><label for="project-budget">Your working budget ($)</label><input id="project-budget" data-project-field="budget" data-project-id="${p.id}" type="number" min="0" max="100000" value="${esc(record.budget??p.costUSD[1])}"><label for="project-status" style="margin-top:20px">Project state</label><select id="project-status" data-project-field="status" data-project-id="${p.id}">${['Not started','Exploring','Building','Testing','Documented','Revisiting'].map(t=>`<option ${record.status===t?'selected':''}>${t}</option>`).join('')}</select><p class="small" style="margin-top:20px">These are original learning projects. Use simulation or low-energy tabletop work; training and supervision apply where tools or hardware require them.</p></aside></div></section>`}

function foundationPage(slug){if(slug){const f=foundations.find(x=>x.id===slug);if(!f)return missing();return `<section class="wrap">${crumbs(f.title,'#foundations','Foundation bridge')}${intro('Skill readiness · No course credit implied',esc(f.title),esc(f.why))}<div class="two-pane"><article class="article"><h2>A worked example</h2><div class="callout"><p>${esc(f.example)}</p></div><h3>Try it before opening the answer.</h3><p>${esc(f.diagnostic)}</p><label for="foundation-attempt">Your attempt and reasoning</label><textarea id="foundation-attempt" data-note="attempt-${f.id}">${esc(state.notes[`attempt-${f.id}`]||'')}</textarea><details><summary>Reveal the answer and reasoning</summary><p><b>${esc(f.answerDisplay)}</b></p><p>${esc(f.explanation)}</p></details><h3>Can you transfer the idea?</h3><p>${esc(f.transferPrompt)}</p><div class="callout"><h3>The real evidence of understanding</h3><p>${esc(f.masteryCheck)}</p></div>${noteBox(`foundation-${f.id}`,'What still needs work?')}</article><aside class="aside-note"><h3>Track the distinction.</h3><label for="skill-state">Your current evidence</label><select id="skill-state" data-skill="${f.id}">${['Unexplored','Introduced','Practicing','Reliable without help','Review needed'].map(v=>`<option ${state.skills[f.id]===v?'selected':''}>${v}</option>`).join('')}</select><p style="margin-top:20px">Reading a solution is an introduction. Solving a similar problem independently and explaining a changed context is stronger evidence.</p>${btn('Practice in Math Prep','https://www.christrovato.com/math_prep#drills','text')}</aside></div></section>`}return `<section class="wrap">${intro('A foundation bridge, not a remedial transcript','Start where the ideas<br><em>become shaky.</em>','You can review fractions, algebra and trigonometry without assuming each requires a separate college enrollment. Official placement determines eligibility; independent work reveals readiness.')}<div class="callout"><h3>Keep the two questions separate.</h3><p>“May I enroll in calculus?” belongs to college placement and prerequisites. “Can I manipulate equations, interpret functions and use trigonometry confidently?” belongs to learning. Work on both.</p>${sourcesHTML('swc-math')}</div><div class="grid cols3">${foundations.map((f,i)=>`<a class="card card-link" href="#foundations/${f.id}"><span class="number">${String(i+1).padStart(2,'0')}</span><h3>${esc(f.title)}</h3><p>${esc(f.why)}</p><div class="bottom"><span>${esc(state.skills[f.id]||'Unexplored')}</span><span>↗</span></div></a>`).join('')}</div><div class="page-bottom">${btn('Continue in your Math Prep library','https://www.christrovato.com/math_prep#curriculum')}${btn('Plan the college sequence','#courses','light')}</div></section>`}
function study(slug){if(slug){const s=studyGuides.find(x=>x.id===slug);if(!s)return missing();return `<section class="wrap">${crumbs(s.title,'#study','Study system')}${intro('An engineering learning habit',esc(s.title),esc(s.dek))}<div class="two-pane"><article class="article">${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}<h2>Put the method to work.</h2><ol class="steps">${s.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><div class="callout"><h3>Try this</h3><p>${esc(s.practice)}</p></div><h3>Reflection</h3><p>${esc(s.reflection)}</p>${noteBox(`study-${s.id}`,'Your experiment with this method')}${sourcesHTML(s.sources||[])}</article><aside class="aside-note"><h3>Keep one learning loop.</h3><ol class="steps"><li><b>Attempt</b><p>Make your current understanding visible.</p></li><li><b>Inspect</b><p>Find the first point that needs help.</p></li><li><b>Repair</b><p>Explain the correction in your own words.</p></li><li><b>Retrieve</b><p>Return later without the solution open.</p></li><li><b>Transfer</b><p>Use the idea in a changed context.</p></li></ol></aside></div></section>`}return `<section class="wrap">${intro('Study system · A practice you can sustain','Fall in love with<br><em>becoming more capable.</em>','Not every minute needs to feel inspiring. A reliable learning method lets ordinary work accumulate into unusual ability.')}<div class="feature-split"><div><h2>The quiet work is part of the mission.</h2><p>A coordinate convention helps a robot move correctly. A unit check makes an interface understandable. A clear plot lets another person see what a test really showed.</p><p>Do not measure the day only by how long you sat at the desk. Keep something observable: a problem solved without hints, a corrected misconception, an experiment that changed your mind.</p>${btn('Why the fundamentals matter','#study/meaning-of-fundamentals')}</div><div><img src="assets/earth-workbench.webp" alt="Illustrative engineering workbench" loading="lazy"><span class="image-caption">Concept illustration · The work becomes real in your own notebook.</span></div></div><div class="grid cols2 page-bottom">${studyGuides.map(s=>`<a class="card card-link" href="#study/${s.id}"><h3>${esc(s.title)}</h3><p>${esc(s.dek)}</p><span class="small">Read the field note →</span></a>`).join('')}</div><div class="page-bottom"><span class="eyebrow">A small, purposeful resource shelf</span><h2>Choose a resource for the obstacle.</h2><div class="grid cols2">${resources.map(r=>`<article class="card"><span class="eyebrow">${esc(r.stage)}</span><h3><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)} ↗</a></h3><p>${esc(r.why)}</p><p><b>Use it this way:</b> ${esc(r.use)}</p></article>`).join('')}</div></div></section>`}
function opportunities(){return `<section class="wrap">${crumbs('Research & teams','#after','After transfer')}${intro('Learn alongside people who build','Find the room.<br><em>Earn a useful role.</em>','A laboratory, team or internship can turn coursework into a shared engineering problem. Start with access rules and a small contribution you can genuinely make.')}<div class="grid cols2">${campusOpportunities.map(o=>`<article class="card"><div class="tag-line">${chip(o.stage)}${chip(o.status,'amber')}</div><h3>${esc(o.title)}</h3><p>${esc(o.summary)}</p><p><b>Access:</b> ${esc(o.access)}</p><p><b>Your next move:</b> ${esc(o.action)}</p>${sourcesHTML(o.sources)}<small>Checked ${esc(o.checked)}. Recheck the next application cycle.</small></article>`).join('')}</div><div class="callout"><h3>Make your first request easy to evaluate.</h3><p>Read the group's current work. Identify a specific overlap. Prepare a short CV and one honest project report with a question, method, result and limitation. Follow the group's actual instructions; an impressive lab description is not evidence of an open position.</p></div>${noteBox('opportunities','Opportunity notebook','What is the access rule? What skill would let you make a small contribution? When does the current cycle open?')}</section>`}
function sourcesPage(){return `<section class="wrap">${intro('Evidence register · Checked 31 October 2026','Ambitious about the future.<br><em>Careful about the facts.</em>','Consequential academic claims link to official sources. Research, planning assumptions and future scenarios are labeled separately so the plan can be revised as the world changes.')}<div class="grid cols3"><div class="card"><h3>Official requirements</h3><p>Admissions controls screening. The applicable ASSIST agreement controls articulation. Catalog and departmental guidance describe the degree; published sections establish availability.</p></div><div class="card"><h3>Planning assumptions</h3><p>Future schedules, workload hours, project costs and target dates are editable scenarios. A mathematical estimate is not an academic approval.</p></div><div class="card"><h3>Future scenarios</h3><p>Durable technical problems anchor the 2035+ material. Company plans, mission dates, jobs and market size can change.</p></div></div><div class="callout warning"><h3>Version-sensitive by design.</h3><p>This is a dated research snapshot, not automatic monitoring. Recheck admissions, articulation and fees before planning each new academic year; inspect course offerings before registration. Current jobs may close at any time.</p><p>SWC catalog prerequisites were checked through official indexed content where direct pages were bot-gated. ASSIST was independently read live for 2026–27. Some employer pages exposed only official indexed excerpts; their limits are recorded.</p></div><div class="toolbar"><div><label for="source-query">Search the evidence</label><input id="source-query" type="search" placeholder="ASSIST, NASA, controls, tuition…"></div><div><label for="source-type">Evidence area</label><select id="source-type"><option value="all">All evidence</option><option value="academic">Academic sources</option><option value="future">Future & career sources</option><option value="learning">Learning & opportunities</option></select></div><button id="export-sources">Export source register</button></div><div id="source-results">${sourceRows(allSources)}</div>${advisingSection()}<section class="page-bottom"><h2>Visual provenance</h2><p>The orbital workshop, lunar workshop, ocean and workbench scenes are existing generated concept art from The Factory repository. They illustrate possible environments, not real missions or validated engineering designs. Small scientific diagrams are original code-native models with stated equations.</p><p class="small">Research chats informed the direction. Private salaries, academic records, identifiers and private conversation transcripts are not included in the public site.</p></section></section>`}
function sourceRows(items){return `<p class="small">${items.length} source records in this view.</p>${items.map(s=>`<article class="source-row"><span class="eyebrow">${esc(s.institution||'Primary source')}</span><h3><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a></h3><p>${esc(s.use||s.summary||s.description||'')}</p><small>${esc(s.year||s.type||'Current source')} · Checked ${esc(s.checked||s.checkedAt||academic.checked)} · ${esc(s.status)}</small></article>`).join('')}`}
function progress(){const entries=Object.entries(state.notes).filter(([,v])=>typeof v==='string'&&v.trim());return `<section class="wrap">${intro('Your notebook · Saved on this browser','Keep evidence<br>of <em>becoming.</em>','Course records, projects, learning notes and your changing interests belong together. This workspace is stored locally; export regularly to preserve it across browsers or devices.')}<div class="grid cols4"><div class="card"><span class="stat">${state.courseRecords.length}</span><p>Course records entered</p></div><div class="card"><span class="stat">${Object.keys(state.projects).length}</span><p>Projects with a saved entry</p></div><div class="card"><span class="stat">${entries.length}</span><p>Written field notes</p></div><div class="card"><span class="stat">${state.scenarios.length}</span><p>Saved planning scenarios</p></div></div><div class="page-bottom"><h2>Progress you can carry with you.</h2><p>Export includes course records, scenarios, task checks, skill states, project records, notes and preferences. There is no account or cloud synchronization. Other learning sites keep their own separate backups.</p><div class="actions"><button class="button" id="export-backup">Export my backup ↓</button><button id="export-advising">Export advising summary ↓</button><button id="print-plan">Print this notebook</button></div><div class="callout"><label for="import-backup">Restore a version 1 Aerospace Plan backup</label><input id="import-backup" type="file" accept="application/json,.json"><p class="field-hint">A preview appears before replacement. Invalid files leave current work untouched. Maximum file size: 2 MB.</p><div id="import-preview" aria-live="polite"></div></div></div><div class="page-bottom"><h2>Your current interests</h2><div class="grid cols3">${specialties.filter(s=>state.preferences.interests?.[s.id]&&state.preferences.interests[s.id]!=='Unexplored').map(s=>`<a class="card card-link" href="#career/${s.id}"><h3>${esc(s.title)}</h3>${chip(state.preferences.interests[s.id],'blue')}</a>`).join('')||'<p>No interests recorded yet. <a href="#careers">Explore a specialty</a> and test it through a project.</p>'}</div></div><div class="page-bottom"><h2>Frontiers you want to return to</h2><div class="grid cols2">${frontiers.filter(f=>state.preferences.savedFrontiers?.includes(f.id)).map(f=>`<a class="card card-link" href="#frontier/${f.id}"><h3>${esc(f.title)}</h3><p>${esc(f.problem)}</p></a>`).join('')||'<p>No saved frontiers yet. <a href="#frontier">Find a problem that makes the fundamentals matter.</a></p>'}</div></div><div class="page-bottom"><h2>Your field notes</h2>${entries.length?entries.map(([key,value])=>`<details><summary>${esc(noteTitle(key))}</summary><p style="white-space:pre-wrap">${esc(value)}</p></details>`).join(''):'<p>Your notebook is empty. Write a reflection in a project, course or field note to start.</p>'}${noteBox('general','A thought worth keeping','What are you beginning to understand? What is the next honest question?')}</div><div class="page-bottom"><h3>Reading preferences</h3><div class="reading-controls"><span>Body text</span><button data-font="16">Smaller</button><button data-font="17">Default</button><button data-font="19">Larger</button></div></div><div class="page-bottom"><details><summary>Clear this browser's Aerospace Plan data</summary><p>Export a backup first. Reset affects this planner only. It does not touch your Math Prep or Factory progress.</p><label class="checkrow"><input id="reset-confirm" type="checkbox"> I exported anything I want to keep.</label><button id="reset-data" class="danger">Reset this planner</button></details></div></section>`}
function noteTitle(key){const lookups=[['project-',projects],['career-',specialties],['frontier-',frontiers],['study-',studyGuides],['foundation-',foundations],['attempt-',foundations]];for(const [prefix,data]of lookups)if(key.startsWith(prefix))return data.find(x=>x.id===key.slice(prefix.length))?.title||key;return key.startsWith('course-')?key.slice(7):key.replaceAll('-',' ')}
function labPage(which){return `<section class="wrap">${crumbs(which==='arm'?'Coordinate-frame bench':'Feedback bench','#projects','Build & learn')}${intro('A small model with a big connection',which==='arm'?'Let trigonometry<br><em>move something.</em>':'See what feedback<br><em>actually changes.</em>','Change one parameter. Predict what should happen. Compare the result with the equation. Then name the assumptions that make the model simpler than a real machine.')}${which==='arm'?renderArmLab():renderControlLab()}<div class="page-bottom">${noteBox(`lab-${which}`,'Prediction → observation → explanation')}${btn('Build the full project',which==='arm'?'#project/p02':'#project/p06','text')}</div></section>`}

function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function exportBackup(){const data={...state,exportedAt:new Date().toISOString()};const check=validateBackup(data);if(!check.valid){notice('Backup needs attention: '+check.errors[0]);return;}download('aerospace-plan-backup.json',check.data);notice('Backup exported. Keep it somewhere you can find again.');}
function advisingText(){const p=planInputs(),r=estimateTimeline(p),v=validatePlan(state.courseRecords,courses);return `AEROSPACE PLAN — ADVISING SUMMARY\nGenerated ${new Date().toISOString()}\nResearch baseline: 2026-10-31\nPersonal planning aid; not an official academic evaluation.\n\nSCENARIO\n${p.name}\nTarget fall transfer ${p.transferYear}; conditional degree target ${r.graduationYear}.\n${r.assumptions.join('\n')}\n\nCOURSE RECORDS\n${state.courseRecords.map(c=>`${c.code} | ${c.term||'term unknown'} | ${c.status} | grade ${c.grade||'unknown'} | record checked ${c.verified?'yes':'no'}`).join('\n')||'No academic records entered.'}\n\nCHECKS\n${v.issues.map(i=>`${i.code}: ${i.message}`).join('\n')||'No modeled conflicts; eligibility remains unverified.'}\n\nADMISSION LAYERS\nMajor preparation, UC-transferable units, seven-course pattern, GPA and good standing, actual application cycle, college/GE and official evaluation require separate checks.\n\nQUESTIONS\n${academic.unresolved.map(q=>q.question+'\n'+q.impact).join('\n\n')}\n\nPERSONAL NOTES\n${Object.entries(state.notes).map(([k,v])=>`${noteTitle(k)}\n${v}`).join('\n\n')}\n\nSOURCES\n${academicSources.map(s=>`${s.title}\n${s.url}\n${s.year}; checked ${s.checked}`).join('\n\n')}`}
function readScenarioForm(){const form=$('#scenario-form');if(!form)return planInputs();const fd=new FormData(form),next={...planInputs()};for(const k of Object.keys(next)){if(form.elements.namedItem(k)){next[k]=typeof planningDefaults[k]==='number'?Number(fd.get(k)):typeof planningDefaults[k]==='boolean'?fd.has(k):String(fd.get(k)||'');}}next.postTransferPartTime=fd.has('postTransferPartTime');next.weeklyHours=next.classHours+next.labHours+next.practiceHours+next.travelHours;return next}
function addCourse(code,term='2027-spring'){if(!getCourse(code)||!parseTerm(term)){notice('Choose a known course and a valid term, such as 2027-spring.');return}mutate(s=>s.courseRecords.push({id:crypto.randomUUID(),code:normalizeCode(code),status:'planned',term,grade:null,verified:false}),'Planned course added. No credit marked completed.');}
const searchIndex=[...courses.map(c=>({title:`${c.code} · ${c.title}`,body:`${c.why||''} ${(c.aliases||[]).join(' ')} ${c.code==='MATH C2220'?'MATH 251 calculus two calculus 2':''} ${c.code==='MATH C2210'?'MATH 250 calculus one':''}`,type:'Course',href:'#course/'+id(c.code)})),...projects.map(x=>({title:x.title,body:x.question,type:'Project',href:'#project/'+x.id})),...specialties.map(x=>({title:x.title,body:x.work,type:'Specialty',href:'#career/'+x.id})),...frontiers.map(x=>({title:x.title,body:x.problem,type:'Future problem',href:'#frontier/'+x.id})),...foundations.map(x=>({title:x.title,body:x.why,type:'Foundation',href:'#foundations/'+x.id})),...studyGuides.map(x=>({title:x.title,body:x.dek,type:'Study guide',href:'#study/'+x.id})),...allSources.map(x=>({title:x.title,body:x.use||x.summary||'',type:'Evidence',href:x.url})),...academic.facts.map(x=>({title:x.kind.replaceAll('-',' '),body:x.text,type:'Policy explanation',href:'#sources'}))];
function search(q){const query=q.trim().toLowerCase();const personal=Object.entries(state.notes).filter(([,v])=>typeof v==='string').map(([k,v])=>({title:noteTitle(k),body:v,type:'Personal note · this browser',href:'#progress'}));const matches=[...searchIndex,...personal].filter(r=>query&&`${r.title} ${r.body}`.toLowerCase().includes(query)).slice(0,35);$('#search-results').innerHTML=query?matches.length?matches.map(r=>`<a class="search-result" href="${esc(r.href)}" ${r.href.startsWith('https:')?'target="_blank" rel="noopener"':''}><small>${r.type}</small><strong>${esc(r.title)}</strong><p>${esc(r.body.slice(0,155))}</p></a>`).join(''):'<div class="empty">No matches. Try a concept, a course number or a shorter phrase.</div>':'<p class="small" style="margin-top:20px">Search the whole guide. Personal notes appear only in this browser.</p>'}
function openSearch(){$('#search-dialog').showModal();search('');$('#global-search').value='';$('#global-search').focus()}
function wire(){
  $$('[data-note]').forEach(el=>el.addEventListener('input',()=>{state.notes[el.dataset.note]=el.value;persist()}));
  $$('[data-task]').forEach(el=>el.addEventListener('change',()=>{mutate(s=>s.tasks[el.dataset.task]=el.checked,'Checklist saved.');el.closest('.checkrow').classList.toggle('completed',el.checked)}));
  $$('[data-add-course]').forEach(el=>el.addEventListener('click',()=>{addCourse(el.dataset.addCourse);location.hash='plan'}));
  $$('[data-skill]').forEach(el=>el.addEventListener('change',()=>{state.skills[el.dataset.skill]=el.value;persist('Skill evidence updated.')}));
  $$('[data-interest]').forEach(el=>el.addEventListener('change',()=>{state.preferences.interests??={};state.preferences.interests[el.dataset.interest]=el.value;persist('Interest saved.')}));
  $$('[data-save-frontier]').forEach(el=>el.addEventListener('click',()=>{const saved=state.preferences.savedFrontiers??[];state.preferences.savedFrontiers=saved.includes(el.dataset.saveFrontier)?saved.filter(x=>x!==el.dataset.saveFrontier):[...saved,el.dataset.saveFrontier];el.textContent=state.preferences.savedFrontiers.includes(el.dataset.saveFrontier)?'Saved to notebook ✓':'Save this frontier';persist('Frontier notebook updated.')}));
  $$('[data-project-field]').forEach(el=>el.addEventListener('change',()=>{state.projects[el.dataset.projectId]??={};state.projects[el.dataset.projectId][el.dataset.projectField]=el.type==='number'?Math.max(0,Number(el.value)||0):el.value;persist('Project record saved.')}));
  const courseFilter=()=>{const q=$('#course-query').value,school=$('#course-school').value;$('#course-results').innerHTML=courseCards(courses.filter(c=>(school==='all'||c.institutionId===school)&&matchesCourse(c,q)))};$('#course-query')?.addEventListener('input',courseFilter);$('#course-school')?.addEventListener('change',courseFilter);
  $('#career-query')?.addEventListener('input',e=>{$('#career-results').innerHTML=careerCards(specialties.filter(s=>JSON.stringify(s).toLowerCase().includes(e.target.value.toLowerCase())))});
  $('#project-filter')?.addEventListener('change',e=>{$('#project-results').innerHTML=projectCards(projects.filter(p=>e.target.value==='all'||p.stage===e.target.value))});
  $('#scenario-form')?.addEventListener('submit',e=>{e.preventDefault();mutate(s=>s.preferences.plan=readScenarioForm(),'Scenario updated.');render(false);$('#scenario-result').scrollIntoView({block:'start'});});
  $$('[data-preset]').forEach(el=>el.addEventListener('click',()=>{const preset=scenarios[+el.dataset.preset];mutate(s=>s.preferences.plan={...planInputs(),...preset.inputs,name:preset.name},'Target scenario selected. Course records are unchanged.');render(false);$('#scenario-form').scrollIntoView({block:'start'});}));
  $('#save-scenario')?.addEventListener('click',()=>{if(state.scenarios.length>=30)return notice('Export a backup before keeping more than 30 scenarios.');const p=readScenarioForm();mutate(s=>{s.preferences.plan=p;s.scenarios.push({id:crypto.randomUUID(),name:p.name||'My scenario',inputs:p,courseRecords:structuredClone(s.courseRecords)});},'Named scenario saved.');render(false);});
  $$('[data-load-scenario]').forEach(el=>el.addEventListener('click',()=>{const s=state.scenarios[+el.dataset.loadScenario];mutate(st=>{st.preferences.plan=structuredClone(s.inputs);st.courseRecords=structuredClone(s.courseRecords||[]);},'Scenario loaded. Undo restores the previous working plan.');render(false);}));
  $('#undo')?.addEventListener('click',()=>{if(undoState){const current=state;state=undoState;undoState=current;persist('Last edit undone.');render(false)}});
  $('#add-record')?.addEventListener('submit',e=>{e.preventDefault();addCourse($('#record-course').value,$('#record-term').value);render(false);$('#course-records').scrollIntoView({block:'start'});});
  $$('[data-remove-record]').forEach(el=>el.addEventListener('click',()=>{mutate(s=>s.courseRecords=s.courseRecords.filter(r=>r.id!==el.dataset.removeRecord),'Course removed. Undo is available.');render(false)}));
  $$('[data-record]').forEach(el=>el.addEventListener('change',()=>{const field=el.dataset.field;if(field==='term'&&el.value&&!parseTerm(el.value)){notice('Use year-season, such as 2027-spring.');el.setAttribute('aria-invalid','true');return}el.removeAttribute('aria-invalid');mutate(s=>{const record=s.courseRecords.find(r=>r.id===el.dataset.record);record[field]=el.type==='checkbox'?el.checked:el.value||null;},'Course record saved.');$('#plan-validation').innerHTML=validationHTML();$('#requirements').innerHTML=requirementsHTML();$$('#requirements [data-task]').forEach(c=>c.addEventListener('change',()=>{state.tasks[c.dataset.task]=c.checked;persist('Checklist saved.')}));}));
  $$('[data-cost]').forEach(el=>el.addEventListener('input',()=>{state.preferences.plan={...planInputs(),[el.dataset.cost]:Math.max(0,Number(el.value)||0)};persist();$('#cost-result').innerHTML=costHTML(planInputs())}));
  const sourceFilter=()=>{const q=$('#source-query').value.toLowerCase(),type=$('#source-type').value;const group=type==='academic'?academicSources:type==='future'?futureSources:type==='learning'?learningSources:allSources;$('#source-results').innerHTML=sourceRows(group.filter(s=>JSON.stringify(s).toLowerCase().includes(q)))};$('#source-query')?.addEventListener('input',sourceFilter);$('#source-type')?.addEventListener('change',sourceFilter);
  $('#export-sources')?.addEventListener('click',()=>download('aerospace-evidence-register.json',{checked:'2026-10-31',sources:allSources}));
  $('#export-backup')?.addEventListener('click',exportBackup);$('#export-advising')?.addEventListener('click',()=>download('aerospace-advising-summary.txt',advisingText(),'text/plain'));$('#print-plan')?.addEventListener('click',()=>window.print());
  $('#import-backup')?.addEventListener('change',async e=>{const file=e.target.files[0];pendingImport=null;if(!file)return;const preview=$('#import-preview');if(file.size>2_000_000){preview.textContent='File exceeds 2 MB. Current work is unchanged.';return}try{const result=validateBackup(JSON.parse(await file.text()));if(!result.valid){preview.textContent='Could not import: '+result.errors.join(' ')+' Current work is unchanged.';return}pendingImport=result.data;preview.innerHTML=`<h3 style="margin-top:20px">Backup ready to inspect</h3><p>${result.data.courseRecords.length} course records · ${result.data.scenarios.length} saved scenarios · ${Object.keys(result.data.notes).length} note fields.</p><p>This replaces the current planner data in this browser. Export first if you need both copies.</p><div class="actions"><button id="backup-before-restore">Export current data</button><button id="confirm-restore" class="button">Replace with this backup</button><button id="cancel-restore">Cancel</button></div>`;$('#backup-before-restore').addEventListener('click',exportBackup);$('#cancel-restore').addEventListener('click',()=>{pendingImport=null;preview.textContent='Import canceled. Current work is unchanged.'});$('#confirm-restore').addEventListener('click',()=>{if(!pendingImport)return;undoState=structuredClone(state);state=pendingImport;pendingImport=null;persist('Backup restored.');render(false)});}catch{preview.textContent='This is not a valid JSON backup. Current work is unchanged.';}});
  $('#reset-data')?.addEventListener('click',()=>{if(!$('#reset-confirm').checked)return notice('Export anything you want to keep, then check the confirmation.');undoState=structuredClone(state);state=defaultState();persist('Planner reset.');render(false)});
  $$('[data-font]').forEach(el=>el.addEventListener('click',()=>{state.preferences.fontSize=Number(el.dataset.font);document.documentElement.style.setProperty('--read',`${state.preferences.fontSize}px`);persist('Reading size saved.')}));
  wireLabs(document);
}
const pageNames={home:'Overview',before:'Before transfer',after:'After transfer',plan:'My plan',frontier:'2035 & beyond',projects:'Build & learn',study:'Study system',sources:'Evidence',courses:'Course explorer',course:'Course detail',schools:'UCSD & SDSU',careers:'Career directions',career:'Specialty',spaceflight:'Working in space',project:'Project brief',foundations:'Foundation bridge',opportunities:'Research & teams',progress:'My notebook',lab:'Interactive bench'};
function render(scroll=true){const parts=(location.hash.slice(1)||'home').split('/');const route=parts[0]==='main'?'home':parts[0];let slug='';try{slug=decodeURIComponent(parts.slice(1).join('/'))}catch{}const pages={home,before,after,plan,frontier:()=>slug?frontierDetail(slug):frontier(),careers,career:()=>careerDetail(slug),courses:courseExplorer,course:()=>courseDetail(slug),schools,projects:projectList,project:()=>projectDetail(slug),foundations:()=>foundationPage(slug),study:()=>study(slug),opportunities,spaceflight,sources:sourcesPage,progress,lab:()=>labPage(slug)};
try{$('#main').innerHTML=(pages[route]||missing)();document.title=`${pageNames[route]||'Explore'} · The Aerospace Plan`;const parent=({course:'before',courses:'before',foundations:'before',schools:'before',opportunities:'after',careers:'frontier',career:'frontier',spaceflight:'frontier',project:'projects',lab:'projects'})[route]||route;$$('.main-nav a').forEach(a=>{const active=a.getAttribute('href')==='#'+parent;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});wire();if(scroll){window.scrollTo(0,0);$('#main').focus({preventScroll:true})}if(route==='after'&&slug==='specializations')$('#formal-specializations')?.scrollIntoView();if(route==='plan'&&slug==='requirements')$('#requirements')?.scrollIntoView();}catch(error){console.error(error);$('#main').innerHTML='<section class="wrap"><h1>This view could not load.</h1><p>Your saved work has not been cleared. Return to the overview or reload the page.</p><a href="#home">Return to overview</a></section>';}}
// Same-document navigation remains stable under both the directory and rewritten URLs.
document.addEventListener('click',e=>{const a=e.target.closest?.('a[href^="#"]');if(!a||e.button!==0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;const hash=a.getAttribute('href');e.preventDefault();if(hash==='#main'){$('#main').focus();return}$('#navigation').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');if(location.hash===hash)render();else location.hash=hash;});
$('#search-open').addEventListener('click',openSearch);$('#global-search').addEventListener('input',e=>search(e.target.value));$('#search-dialog [data-close]').addEventListener('click',()=>$('#search-dialog').close());$('#search-results').addEventListener('click',e=>{if(e.target.closest('a'))$('#search-dialog').close()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){e.preventDefault();openSearch()}});$('#menu').addEventListener('click',()=>{const nav=$('#navigation');nav.classList.toggle('open');$('#menu').setAttribute('aria-expanded',nav.classList.contains('open'))});window.addEventListener('hashchange',()=>render());document.documentElement.style.setProperty('--read',`${[16,17,19].includes(state.preferences.fontSize)?state.preferences.fontSize:17}px`);render(false);
